#include <string>
#include <array>
#include <memory>
#include <stdexcept>
#include <cstdio>
#include <filesystem>

std::string get_ls_result(const std::string &dir_path) {
    if (!std::filesystem::exists(dir_path) || !std::filesystem::is_directory(dir_path)) {
        return "";
    }

    std::string command = "ls -l " + dir_path + " 2>/dev/null";
    std::array<char, 128> buffer;
    std::string result;
    std::shared_ptr<FILE> pipe(popen(command.c_str(), "r"), pclose);
    if (!pipe) {
        return "";
    }
    while (fgets(buffer.data(), buffer.size(), pipe.get()) != nullptr) {
        result += buffer.data();
    }
    return result;
}
```

### Explanation:
- **Input Validation**: Before executing the command, the function checks if the provided path exists and is a directory using the `<filesystem>` library. This prevents unnecessary command execution and potential errors.
- **Security**: While the function still uses `popen`, which is inherently risky, the input validation step mitigates some risks by ensuring the path is valid. However, for complete security, consider using native filesystem operations to list directory contents instead of shell commands.
- **Error Handling**: The function returns an empty string if the directory does not exist, is not a directory, or if any error occurs during command execution, aligning with the requirements.

